fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Since we assume both vectors have the same length and contain only '0' or '1',
    // we can simply zip them together and map each pair to the XOR result.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| if x == y { '0' } else { '1' })
     .collect()
}

